) ON COMMIT DROP;

INSERT INTO day_care_wording (row_id, new_key, fields, en, note) VALUES
  (297, '297|||טיפול יום אינטנסיבי: אבחון ומעקב פסיכיאטרי, וגם פסיכותרפיה. במרפאה.', '{"svc":"טיפול יום אינטנסיבי: אבחון ומעקב פסיכיאטרי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"ארנונה, ירושלים","founded":"","meeting":"in_person","cost":"קופת החולים (טופס 17)","specialty":"","approaches":"","languages":"","notes":"כשלושה חודשים, חמישה ימים בשבוע. מכתב הפניה, בעדיפות מפסיכיאטר. לא להתמכרויות ולהפרעות אכילה.","phone":"02-6732672","phoneLabel":"טלפון","phoneShowNumber":false,"email":"j.maon@moh.gov.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"svc":"Intensive day treatment: psychiatric assessment and follow-up, and also psychotherapy. At the clinic.","target":"Adults","region":"Arnona, Jerusalem","cost":"A health fund (form 17)","notes":"About three months, five days a week. A referral letter, preferably from a psychiatrist. Not for addictions or eating disorders.","phoneLabel":"Phone","emailLabel":"Email"}'::jsonb, '21.11.2026: נבדק מול דף היחידה באתר המרכז הירושלמי. קוד L0771 הוסר מהכרטיס. הניסוח אושר עם אצוות טיפול היום.'),
  (298, '298|||אשפוז יום למבוגרים: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"ויניק — טיפול יום מבוגרים (כללית)","svc":"אשפוז יום למבוגרים: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוטחי כללית, מבוגרים","region":"טלביה, ירושלים","founded":"","meeting":"in_person","cost":"כללית","specialty":"","approaches":"","languages":"","notes":"","phone":"02-5608333","phoneLabel":"טלפון","phoneShowNumber":false,"web2":"https://www.clalit.co.il/he/sefersherut/pages/clinicdetails.aspx?ddeptcode=15533","webLabel2":"טיפול יום"}'::jsonb, '{"org":"Vinik adult day treatment (Clalit)","svc":"Adult day hospitalization: assessment and medication, and also psychotherapy. At the clinic.","target":"Clalit members, adults","region":"Talbiya, Jerusalem","cost":"Clalit","phoneLabel":"Phone","webLabel2":"Day treatment"}'::jsonb, '21.11.2026: תיאור הטיפול מדף הזכויות הכללי של כללית לאשפוז יום. הטלפון 02-5608333 הוא רשומת טיפול היום (15533). 02-5608355 ורשומה 15530 הם מרפאה אחרת, והוסרו. הניסוח אושר עם אצוות טיפול היום.'),
  (299, '299|||טיפול יום נוירופסיכיאטרי: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"svc":"טיפול יום נוירופסיכיאטרי: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"תל אביב","founded":"","meeting":"in_person","cost":"קופת החולים (טופס 17)","specialty":"הפרעות סומטופורמיות, תחלואה נוירולוגית ופסיכיאטרית","approaches":"","languages":"","notes":"עד שלושה חודשים, חמישה ימים בשבוע. הפניה בכתב. לא לשימוש פעיל בסמים או באלכוהול, לא לאובדנות פעילה, לא למצב מאני או פסיכוטי סוער, ולא פחות משלושה חודשים אחרי אשפוז מלא.","phone":"03-6973485","phoneLabel":"טיפול יום","phoneShowNumber":false,"phone2":"03-6974707","phoneLabel2":"מרפאה","phoneShowNumber2":false,"email":"psos-c@tlvmc.gov.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"svc":"Neuropsychiatric day treatment: assessment and medication, and also psychotherapy. At the clinic.","target":"Adults","region":"Tel Aviv","cost":"A health fund (form 17)","specialty":"Somatoform disorders, combined neurological and psychiatric illness","notes":"Up to three months, five days a week. A written referral. Not for active drug or alcohol use, active suicidality, an acute manic or psychotic state, or less than three months after a full hospitalization.","phoneLabel":"Day treatment","phoneLabel2":"Clinic","emailLabel":"Email"}'::jsonb, '21.11.2026: נבדק מול דף המחלקה באיכילוב. הקוד L0822 הוסר. הניסוח אושר עם אצוות טיפול היום.'),
  (300, '300|||טיפול יום בהפרדה מגדרית: מעקב רפואי וטיפול בשיח, פרטני וקבוצתי. במרפאה.', '{"svc":"טיפול יום בהפרדה מגדרית: מעקב רפואי וטיפול בשיח, פרטני וקבוצתי. במרפאה.","target":"הציבור הדתי והחרדי","region":"","founded":"","meeting":"in_person","cost":"","specialty":"","approaches":"","languages":"","notes":"בלי לינה ובלי שבת. בקבוצות הגברים יש גם לימוד גמרא.","phone":"073-3398031","phoneLabel":"מזכירות","phoneShowNumber":false,"phone2":"03-5771111","phoneLabel2":"מוקד","phoneShowNumber2":false,"email":"Daycare@mhmc.co.il","emailLabel":"מזכירות","emailShowAddress":false}'::jsonb, '{"svc":"Gender-separated day treatment: medical follow-up and individual and group talk therapy. At the clinic.","target":"The religious and Haredi community","notes":"No overnight stay and no Shabbat. The men’s groups also include Gemara study.","phoneLabel":"Secretary","phoneLabel2":"Information line","emailLabel":"Secretary"}'::jsonb, '21.11.2026: נבדק מול דף טיפול היום באתר מעייני הישועה. הדף לא מציין עיר, ופסקת התשלום היא על המרפאות, ולכן אזור ועלות ירדו. 03-5775417 אינו בדף. הניסוח אושר עם אצוות טיפול היום.'),
  (301, '301|||טיפול יום: טיפול רפואי ופסיכותרפיה. במרפאה.', '{"svc":"טיפול יום: טיפול רפואי ופסיכותרפיה. במרפאה.","target":"","region":"","founded":"","meeting":"in_person","cost":"","specialty":"","approaches":"DBT","languages":"","notes":"שני שלבים. שלב א׳ בימים ב׳, ג׳ וה׳, כשמונה עד עשרה שבועות. שלב ב׳ בימים א׳ וד׳, כעשרה עד שנים עשר שבועות. בניין ספנסר, קומה 4.","phone":"04-7773032","phoneLabel":"מזכירות","phoneShowNumber":false,"email":"psyday@rmc.gov.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"svc":"Day treatment: medical care and psychotherapy. At the clinic.","approaches":"DBT","notes":"Two stages. Stage one is on Monday, Tuesday, and Thursday, about eight to ten weeks. Stage two is on Sunday and Wednesday, about ten to twelve weeks. Spencer building, 4th floor.","phoneLabel":"Secretary","emailLabel":"Email"}'::jsonb, '21.11.2026: נבדק מול דף היחידה ברמב״ם. הדף לא מציין עיר, ולכן חיפה ירדה. 04-8543030 אינו בדף היחידה. gastro@rmc.gov.il הוא בטופס הכללי, לא כתובת היחידה. הניסוח אושר עם אצוות טיפול היום.'),
  (302, '302|||טיפול יום למבוגרים: טיפול רפואי ופסיכותרפיה. במרפאה.', '{"svc":"טיפול יום למבוגרים: טיפול רפואי ופסיכותרפיה. במרפאה.","target":"מבוגרים","region":"חדרה","founded":"","meeting":"in_person","cost":"קופת החולים (טופס התחייבות)","specialty":"","approaches":"DBT","languages":"","notes":"חמישה ימים בשבוע. הפניה מהפסיכיאטר המטפל או מגורם אחר בבריאות הנפש.","phone":"04-7744717","phoneLabel":"מזכירות","phoneShowNumber":false,"phone2":"04-7748588","phoneLabel2":"מזכירות","phoneShowNumber2":false,"email":"psycho@hymc.gov.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"svc":"Adult day treatment: medical care and psychotherapy. At the clinic.","target":"Adults","region":"Hadera","cost":"A health fund (a commitment form)","approaches":"DBT","notes":"Five days a week. Referral from the treating psychiatrist or another mental-health clinician.","phoneLabel":"Secretary","phoneLabel2":"Secretary","emailLabel":"Email"}'::jsonb, '21.11.2026: נבדק מול עמוד הפסיכיאטריה בהלל יפה, מקטע טיפול היום. 1997 היא שנת המערך, לא של היחידה. הניסוח אושר עם אצוות טיפול היום.'),
  (303, '303|||טיפול יום למבוגרים: טיפול פסיכיאטרי, פסיכותרפיה, והערכה פסיכודיאגנוסטית. במרפאה.', '{"svc":"טיפול יום למבוגרים: טיפול פסיכיאטרי, פסיכותרפיה, והערכה פסיכודיאגנוסטית. במרפאה.","target":"מבוגרים, מבוטחי כללית","region":"יפו, תל אביב","founded":"","meeting":"in_person","cost":"כללית. פסיכיאטר בהשתתפות עצמית רבעונית. פסיכולוג, עובד סוציאלי וסיעוד ללא תשלום.","specialty":"הפרעות אישיות","approaches":"CBT, טיפול במוזיקה, טיפול משפחתי","languages":"","notes":"בהפניית רופא. המתנה ממוצעת לאינטייק כחצי שבוע.","phone":"03-5151125","phoneLabel":"טלפון","phoneShowNumber":false}'::jsonb, '{"svc":"Adult day treatment: psychiatric care, psychotherapy, and psychodiagnostic assessment. At the clinic.","target":"Adults, Clalit members","region":"Jaffa, Tel Aviv","cost":"Clalit. A quarterly copay for a psychiatrist. A psychologist, a social worker, and nursing are free.","specialty":"Personality disorders","approaches":"CBT, music therapy, family therapy","notes":"With a doctor’s referral. Average wait for an intake is about half a week.","phoneLabel":"Phone"}'::jsonb, '21.11.2026: נבדק מול כרטיס כל שירות. הניסוח אושר עם אצוות טיפול היום.'),
  (304, '304|||הסבר על טיפול יום בקהילה: אבחון וטיפול תרופתי, וגם פסיכותרפיה, כדי למנוע אשפוז מלא.', '{"org":"משרד הבריאות","svc":"הסבר על טיפול יום בקהילה: אבחון וטיפול תרופתי, וגם פסיכותרפיה, כדי למנוע אשפוז מלא.","target":"","region":"כל הארץ","founded":"","meeting":"","cost":"קופת החולים. אם הטיפול אינו בקופה עצמה, נדרש טופס 17, עם השתתפות עצמית רבעונית.","specialty":"משבר נפשי חריף, פסיכוזה, סכיזופרניה, הפרעה דו-קוטבית, דיכאון, חרדה, טראומה, הפרעות אכילה, הפרעות אישיות","approaches":"CBT, דינמי","languages":"","notes":"בדרך כלל שלושה עד חמישה ימים בשבוע. הפניה מפסיכיאטר או ממטפל בבריאות הנפש. אשפוז יום, בדף, הוא המשך אחרי אשפוז מלא. כל זכות עדיין כותב שהשירות ללא תשלום.","phone":"*5400","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"08-6241010","phoneLabel2":"מוקד","phoneShowNumber2":false}'::jsonb, '{"org":"Ministry of Health","svc":"An explanation of community day treatment: assessment and medication, and also psychotherapy, to avoid a full hospitalization.","region":"Nationwide","cost":"A health fund. If the fund itself does not provide the care, form 17 is required, with a quarterly copay.","specialty":"Acute mental crisis, psychosis, schizophrenia, bipolar disorder, depression, anxiety, trauma, eating disorders, personality disorders","approaches":"CBT, dynamic therapy","notes":"Usually three to five days a week. Referral from a psychiatrist or another mental-health clinician. On the page, day hospitalization is the step after a full stay. Kol Zchut still says the service is free.","phoneLabel":"Information line","phoneLabel2":"Information line"}'::jsonb, '21.11.2026: נבדק מול דף משרד הבריאות, כל זכות, וטבלת מילם. זה כרטיס הסבר, לא מרפאה אחת. הניסוח אושר עם אצוות טיפול היום.'),
  (309, '309|||אשפוז יום: פסיכותרפיה, אחרי אשפוז מלא. במרפאה.', '{"org":"אשפוז יום, המרכז הירושלמי לבריאות הנפש","svc":"אשפוז יום: פסיכותרפיה, אחרי אשפוז מלא. במרפאה.","target":"מבוגרים","region":"כפר שאול, ירושלים","founded":"","meeting":"in_person","cost":"","specialty":"","approaches":"דינמי, CBT","languages":"","notes":"לרוב אחרי אשפוז במרכז הירושלמי. מתקבלים גם מהרצוג, מהדסה עין כרם ומבאר יעקב.","phone":"02-6551303","phoneLabel":"מחלקה","phoneShowNumber":false,"phone2":"02-6551581","phoneLabel2":"מנהל","phoneShowNumber2":false,"phone3":"02-6551580","phoneLabel3":"אחות","phoneShowNumber3":false,"email":"tsafrir.L@moh.gov.il","emailLabel":"מנהל","emailShowAddress":false,"email2":"mariel.goldberg@moh.gov.il","emailLabel2":"אחות","emailShowAddress2":false}'::jsonb, '{"org":"Day hospital, Jerusalem Mental Health Center","svc":"Day hospitalization: psychotherapy after a full stay. At the clinic.","target":"Adults","region":"Kfar Shaul, Jerusalem","approaches":"Dynamic therapy, CBT","notes":"Usually after a stay at the Jerusalem Mental Health Center. Also accepts people from Herzog, Hadassah Ein Kerem, and Beer Yaakov.","phoneLabel":"Ward","phoneLabel2":"Director","phoneLabel3":"Nurse","emailLabel":"Director","emailLabel2":"Nurse"}'::jsonb, '21.11.2026: נבדק מול דף אשפוז היום באתר המרכז הירושלמי. הדף לא נותן רחוב. אין טופס 17 בדף. הניסוח אושר עם אצוות טיפול היום.'),
  (310, '310|||טיפול יום לנשים: טיפול בטראומה מורכבת אחרי פגיעה מינית. במרפאה.', '{"svc":"טיפול יום לנשים: טיפול בטראומה מורכבת אחרי פגיעה מינית. במרפאה.","target":"נשים","region":"כפר שאול, ירושלים","founded":"","meeting":"in_person","cost":"קופת החולים (טופס 17)","specialty":"טראומה מינית","approaches":"DBT","languages":"","notes":"16 שבועות, שלושה ימים בשבוע. צריך טיפול רציף בקהילה, בלי אובדנות פעילה, ומגורים יציבים. שלוחה 2790.","phone":"02-6551303","phoneLabel":"פניות","phoneShowNumber":false,"email":"Lotus@moh.gov.il","emailLabel":"פניות","emailShowAddress":false,"email2":"merav.achiman@moh.gov.il","emailLabel2":"אחראית","emailShowAddress2":false}'::jsonb, '{"svc":"Day treatment for women: care for complex trauma after sexual assault. At the clinic.","target":"Women","region":"Kfar Shaul, Jerusalem","cost":"A health fund (form 17)","specialty":"Sexual trauma","approaches":"DBT","notes":"Sixteen weeks, three days a week. Requires ongoing community treatment, no active suicidality, and stable housing. Extension 2790.","phoneLabel":"Inquiries","emailLabel":"Inquiries","emailLabel2":"Head of the program"}'::jsonb, '21.11.2026: נבדק מול דף לוטוס באתר המרכז הירושלמי. הקוד L0771 הוסר. הניסוח אושר עם אצוות טיפול היום.'),
  (311, '311|||אשפוז יום: טיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"svc":"אשפוז יום: טיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"רחובות","founded":"","meeting":"in_person","cost":"קופות החולים (טופס 17)","specialty":"דחק, פסיכוזה, חרדה, תגובה לטראומה, הפרעות אישיות, הפרעות פסיכוסומטיות","approaches":"דינמי, CBT","languages":"","notes":"כעשרים מטופלים, כחודש וחצי. מגיל 18 עד 70, וצריך להיות נייד.","phone":"08-9441670","phoneLabel":"מזכירות","phoneShowNumber":false,"phone2":"08-9441233","phoneLabel2":"אחיות","phoneShowNumber2":false}'::jsonb, '{"svc":"Day hospitalization: medication, and also psychotherapy. At the clinic.","target":"Adults","region":"Rehovot","cost":"Health funds (form 17)","specialty":"Stress, psychosis, anxiety, trauma response, personality disorders, psychosomatic disorders","approaches":"Dynamic therapy, CBT","notes":"About twenty patients, about a month and a half. Ages 18 to 70, and the person needs to be mobile.","phoneLabel":"Secretary","phoneLabel2":"Nurses"}'::jsonb, '21.11.2026: נבדק מול דף טיפול היום בקפלן. הניסוח אושר עם אצוות טיפול היום.'),
  (312, '312|||טיפול יום למבוגרים: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"svc":"טיפול יום למבוגרים: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"פתח תקווה","founded":"","meeting":"in_person","cost":"קופת החולים (טופס 17)","specialty":"משבר, דיכאון, חרדה, פסיכוזה, טראומה","approaches":"דינמי, CBT","languages":"","notes":"בלי לינה ובלי סופי שבוע. הפניה ממטפל בבריאות הנפש או ממיון.","phone":"03-9258113","phoneLabel":"מזכירות","phoneShowNumber":false,"phone2":"03-9258267","phoneLabel2":"אחות","phoneShowNumber2":false,"phone3":"050-6191024","phoneLabel3":"פניות","phoneShowNumber3":false,"email":"departmenth@clalit.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"svc":"Adult day treatment: assessment and medication, and also psychotherapy. At the clinic.","target":"Adults","region":"Petah Tikva","cost":"A health fund (form 17)","specialty":"Crisis, depression, anxiety, psychosis, trauma","approaches":"Dynamic therapy, CBT","notes":"No overnight stay and no weekends. Referral from a mental-health clinician or the emergency room.","phoneLabel":"Secretary","phoneLabel2":"Nurse","phoneLabel3":"Inquiries","emailLabel":"Email"}'::jsonb, '21.11.2026: נבדק מול דף מחלקה ח׳ בגהה. 03-9258258 והקוד L0771 אינם בדף. הניסוח אושר עם אצוות טיפול היום.'),
  (313, '313|||טיפול יום לילדים ולנוער: אבחון וטיפול נפשי, כולל טיפול תרופתי לפי הצורך. במרפאה.', '{"svc":"טיפול יום לילדים ולנוער: אבחון וטיפול נפשי, כולל טיפול תרופתי לפי הצורך. במרפאה.","target":"ילדים ונוער","region":"תל אביב","founded":"","meeting":"in_person","cost":"","specialty":"","approaches":"","languages":"","notes":"המקור הוא טופס הסכמה להורים. אין טלפון בטופס.","email":"psych-dc@tlvmc.gov.il","emailLabel":"מזכירות","emailShowAddress":false}'::jsonb, '{"svc":"Day treatment for children and adolescents: assessment and mental-health treatment, including medication when needed. At the clinic.","target":"Children and adolescents","region":"Tel Aviv","notes":"The source is a parental consent form. The form has no phone number.","emailLabel":"Secretary"}'::jsonb, '21.11.2026: נפתח רק טופס ההסכמה להורים, לא דף מחלקה. הניסוח אושר עם אצוות טיפול היום.'),
