-- glossary_card_links.card_key and the organization-member keys follow
-- directory_card_edits.card_key through ON UPDATE CASCADE.
-- site_audit_entries.card_keys is a plain array, so it is rewritten first.

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE(
      (SELECT w.new_key FROM directory_card_edits c JOIN day_care_wording w ON w.row_id = c.row_id WHERE c.card_key = k),
      k
    )
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN directory_card_edits c ON c.card_key = k
  JOIN day_care_wording w ON w.row_id = c.row_id
  WHERE c.card_key IS DISTINCT FROM w.new_key
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM day_care_wording w
WHERE c.row_id = w.row_id;

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN day_care_wording w ON w.row_id = c.row_id
WHERE e.entry_id = c.entry_id;

-- Pins that still named a dropped branch or a replaced number.
DELETE FROM directory_entry_locations
WHERE (row_id = 314 AND label = 'אתיופיה')
   OR (row_id = 330 AND label = 'אבן יהודה');

UPDATE directory_card_edits c
SET sites = (
  SELECT COALESCE(jsonb_agg(
    CASE
      WHEN c.row_id = 298 AND elem->>'label' = 'טלביה' THEN jsonb_set(elem, '{phone}', '"02-5608333"')
      WHEN c.row_id = 300 AND elem->>'label' = 'בני ברק' THEN jsonb_set(elem, '{phone}', '"073-3398031"')
      WHEN c.row_id = 301 AND elem->>'label' = 'חיפה' THEN jsonb_set(elem, '{phone}', '"04-7773032"')
      WHEN c.row_id = 312 AND elem->>'phone' = '03-9258258' THEN jsonb_set(elem, '{phone}', '"03-9258113"')
      WHEN c.row_id = 314 AND elem->>'label' = 'עין כרם' THEN jsonb_set(elem, '{phone}', '"02-6779203"')
      ELSE elem
    END
  ), '[]'::jsonb)
  FROM jsonb_array_elements(c.sites) elem
  WHERE NOT (
    (c.row_id = 314 AND elem->>'label' = 'אתיופיה')
    OR (c.row_id = 330 AND elem->>'label' = 'אבן יהודה')
  )
)
WHERE c.row_id IN (298, 300, 301, 312, 314, 330)
  AND jsonb_typeof(c.sites) = 'array';

